using System;using System.Collections.Generic;using System.Runtime.InteropServices;using System.Text;using System.IO;
public class LimbusRead {
[DllImport("kernel32.dll",SetLastError=true)]static extern IntPtr OpenProcess(uint a,bool b,int c);[DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr h);[DllImport("kernel32.dll")]static extern UIntPtr VirtualQueryEx(IntPtr h,IntPtr p,out M m,UIntPtr n);[DllImport("kernel32.dll")]static extern bool ReadProcessMemory(IntPtr h,IntPtr p,byte[] b,UIntPtr n,out UIntPtr r);
[StructLayout(LayoutKind.Sequential)]struct M{public IntPtr Base,Alloc;public uint AllocProtect;public ushort Partition;public UIntPtr Size;public uint State,Protect,Type;}
IntPtr h;public LimbusRead(int pid){h=OpenProcess(0x410,false,pid);if(h==IntPtr.Zero)throw new Exception("Read-only OpenProcess failed "+Marshal.GetLastWin32Error());}public void Close(){CloseHandle(h);}byte[] Read(long p,int n){var b=new byte[n];UIntPtr r;ReadProcessMemory(h,new IntPtr(p),b,(UIntPtr)n,out r);return b;}long I64(long p){return BitConverter.ToInt64(Read(p,8),0);}string Str(long p){return Encoding.UTF8.GetString(Read(p,160)).Split('\0')[0];}
void Scan(Action<long,byte[],int> act){long pos=0;M m;while(VirtualQueryEx(h,new IntPtr(pos),out m,(UIntPtr)Marshal.SizeOf(typeof(M)))!=UIntPtr.Zero){long start=m.Base.ToInt64(),size=(long)m.Size.ToUInt64();if(size<=0||start+size<=pos)break;pos=start+size;if(m.State!=0x1000||(m.Protect&0x101)!=0||m.Type!=0x20000)continue;for(long off=0;off<size;off+=4*1024*1024-4096){int len=(int)Math.Min(4*1024*1024,size-off);byte[] b=new byte[len];UIntPtr got;ReadProcessMemory(h,new IntPtr(start+off),b,(UIntPtr)len,out got);int n=(int)got.ToUInt64();if(n>0)act(start+off,b,n);}}}
public void Discover(string path){var wanted=new HashSet<string>(new[]{"UserDataManager","UserSkinData","UserEgoListData","UserPersonalityData","Personality","PersonalityList","PersonalityStaticData","Ego","EgoList","EgoStaticData","SkinStaticData","SkinPersonalityStaticData","GachaStaticData","GachaBannerInfo","GachaElementGroup"});var names=new Dictionary<long,string>();Console.WriteLine("Finding runtime model names");Scan((a,b,n)=>{string s=Encoding.GetEncoding(28591).GetString(b,0,n);if(s.IndexOf("\0Personality\0",StringComparison.Ordinal)<0)return;foreach(string name in wanted){int ix=0;while((ix=s.IndexOf(name+"\0",ix,StringComparison.Ordinal))>=0){if(ix==0||s[ix-1]=='\0')names[a+ix]=name;ix+=name.Length;}}});Console.WriteLine("Resolving runtime model classes");var found=new HashSet<string>();Scan((a,b,n)=>{for(int i=16;i<n-232;i+=8){long v=BitConverter.ToInt64(b,i);string name;if(!names.TryGetValue(v,out name))continue;long klass=a+i-16; // Validate the class self pointer, which distinguishes real Il2CppClass from other metadata references.
if(BitConverter.ToInt64(b,i+104)!=klass)continue;found.Add(name+","+klass.ToString("X"));}});File.WriteAllLines(path,found);Console.WriteLine("Classes "+found.Count);}
public void Fields(string classes,string output){var lines=new List<string>();foreach(var line in File.ReadAllLines(classes)){var v=line.Split(',');long k=Convert.ToInt64(v[1],16);var c=Read(k,384);long fp=BitConverter.ToInt64(c,128);lines.Add("CLASS "+line);for(int i=0;i<100;i++){var f=Read(fp+i*32,32);long np=BitConverter.ToInt64(f,0),parent=BitConverter.ToInt64(f,16);if(parent!=k)break;string name=Str(np);int off=BitConverter.ToInt32(f,24);lines.Add(name+"="+off+" type="+BitConverter.ToInt64(f,8).ToString("X"));}}File.WriteAllLines(output,lines);}
public void Objects(string classes,string output){var targets=new Dictionary<long,string>();foreach(var line in File.ReadAllLines(classes)){var v=line.Split(',');targets[Convert.ToInt64(v[1],16)]=v[0];}var seen=new HashSet<long>();var rows=new List<string>();Scan((a,b,n)=>{for(int i=0;i<n-512;i+=8){long k=BitConverter.ToInt64(b,i);string name;if(!targets.TryGetValue(k,out name)||!seen.Add(a+i))continue;if(BitConverter.ToInt64(b,i+8)!=0)continue;var vals=new string[124];for(int j=16;j<512;j+=4)vals[(j-16)/4]=BitConverter.ToInt32(b,i+j).ToString();rows.Add(name+","+(a+i).ToString("X")+","+String.Join(",",vals));}});File.WriteAllLines(output,rows);Console.WriteLine("Object candidates "+rows.Count);}
public string ClassInfo(long k){M m;long p=I64(k+16);VirtualQueryEx(h,new IntPtr(p),out m,(UIntPtr)Marshal.SizeOf(typeof(M)));return Str(p)+" namespace="+Str(I64(k+24))+" name="+p.ToString("X")+" region="+m.Base.ToInt64().ToString("X")+" size="+m.Size.ToUInt64();} public string Utf16(long p){var b=Read(p,20);int n=BitConverter.ToInt32(b,16);if(n<0||n>10000)return "";return Encoding.Unicode.GetString(Read(p+20,n*2));}
public string Dump(long p,int n){var b=Read(p,n);var rows=new List<string>();for(int i=0;i+8<=n;i+=8)rows.Add(i+": "+BitConverter.ToInt32(b,i)+" "+BitConverter.ToInt32(b,i+4)+" ptr="+BitConverter.ToInt64(b,i).ToString("X"));return Str(I64(I64(p)+16))+"\n"+String.Join("\n",rows);}
public void DiscoverMore(long baseAddr,int size,string output){var wanted=new[]{"SkinSystem","User","UserDataManager","UserDataModel","UserEgoListData","UserPersonalityListData","UserSkinData","SkinListView","SkinListViewItem","CurrentGachaInfomation","GachaUIPresenter","Account"};var names=new Dictionary<long,string>();string str=Encoding.GetEncoding(28591).GetString(Read(baseAddr,size));foreach(string name in wanted){int ix=0;while((ix=str.IndexOf(name+"\0",ix,StringComparison.Ordinal))>=0){if(ix==0||str[ix-1]=='\0')names[baseAddr+ix]=name;ix+=name.Length;}}var found=new HashSet<string>();Scan((a,b,n)=>{for(int j=16;j<n-232;j+=8){long v=BitConverter.ToInt64(b,j);string name;if(!names.TryGetValue(v,out name))continue;long k=a+j-16;if(BitConverter.ToInt64(b,j+104)==k)found.Add(name+","+k.ToString("X"));}});File.WriteAllLines(output,found);Console.WriteLine("Extra classes "+found.Count);}
public long Ptr(long p){return I64(p);}public int Int(long p){return BitConverter.ToInt32(Read(p,4),0);}public float Float(long p){return BitConverter.ToSingle(Read(p,4),0);}public byte Byte(long p){return Read(p,1)[0];}public string Name(long p){return Str(I64(I64(p)+16));}
public long[] List(long p){int n=Int(p+24);if(n<0||n>100000)return new long[0];long a=I64(p+16);var b=Read(a+32,n*8);var result=new long[n];for(int i=0;i<n;i++)result[i]=BitConverter.ToInt64(b,i*8);return result;}
public string[] Dict(long p){int n=Int(p+32);if(n<0||n>100000)return new string[0];long a=I64(p+24);var b=Read(a+32,n*24);var result=new List<string>();for(int i=0;i<n;i++){int next=BitConverter.ToInt32(b,i*24+4);if(next < -1)continue;int key=BitConverter.ToInt32(b,i*24+8);long value=BitConverter.ToInt64(b,i*24+16);result.Add(key+","+value.ToString("X"));}return result.ToArray();}
public int[] IntList(long p){int n=Int(p+24);if(n<0||n>100000)return new int[0];long a=I64(p+16);var b=Read(a+32,n*4);var result=new int[n];for(int i=0;i<n;i++)result[i]=BitConverter.ToInt32(b,i*4);return result;}
public int[] Set(long p){int n=Int(p+36);if(n<0||n>100000)return new int[0];long a=I64(p+24);var b=Read(a+32,n*12);var result=new List<int>();for(int i=0;i<n;i++){if(BitConverter.ToInt32(b,i*12)>=0)result.Add(BitConverter.ToInt32(b,i*12+8));}return result.ToArray();}
}